"use client";

import { MapContainer, TileLayer, Marker, Popup, useMap } from "react-leaflet";
import L from "leaflet";
import { useEffect, useState } from "react";
import { Avatar } from "@/components/ui/Avatar";
import { renderToStaticMarkup } from "react-dom/server";
import { Calendar, MapPin } from "lucide-react";
import { cn } from "@/lib/utils";

// Fix Leaflet icon issue
const DefaultIcon = L.icon({
    iconUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
    shadowUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
    iconSize: [25, 41],
    iconAnchor: [12, 41],
});
L.Marker.prototype.options.icon = DefaultIcon;

interface MapViewProps {
    center: [number, number];
    zoom: number;
    markers: any[];
}

export default function MapView({ center, zoom, markers }: MapViewProps) {
    const [isMounted, setIsMounted] = useState(false);

    useEffect(() => {
        setIsMounted(true);
    }, []);

    if (!isMounted) return <div className="w-full h-full bg-slate-100 animate-pulse" />;

    return (
        <MapContainer
            center={center}
            zoom={zoom}
            scrollWheelZoom={true}
            className="w-full h-full z-0"
        >
            <TileLayer
                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
            />

            {markers.map((marker) => (
                <CustomMarker key={marker.id} marker={marker} />
            ))}
        </MapContainer>
    );
}

function CustomMarker({ marker }: { marker: any }) {
    const map = useMap();

    const createAvatarIcon = (name: string, color: string) => {
        const html = renderToStaticMarkup(
            <div className="relative flex flex-col items-center">
                <div
                    className="w-10 h-10 rounded-full border-[3px] shadow-lg flex items-center justify-center overflow-hidden bg-white"
                    style={{ borderColor: color }}
                >
                    <span className="font-bold text-[10px]" style={{ color }}>{name[0]}</span>
                </div>
                <div className="glass px-2 py-0.5 rounded-full mt-1 border border-black/5">
                    <span className="text-[8px] font-black" style={{ color }}>{name}</span>
                </div>
            </div>
        );
        return L.divIcon({
            html,
            className: "custom-div-icon",
            iconSize: [40, 60],
            iconAnchor: [20, 50],
        });
    };

    const createEventIcon = (color: string) => {
        const html = renderToStaticMarkup(
            <div className="relative flex flex-col items-center group">
                <div className="w-12 h-12 bg-white rounded-2xl shadow-xl flex items-center justify-center border border-black/5 rotate-45 group-hover:scale-110 transition-transform">
                    <div className="-rotate-45">
                        <Calendar className="w-6 h-6" style={{ color }} />
                    </div>
                </div>
            </div>
        );
        return L.divIcon({
            html,
            className: "custom-div-icon",
            iconSize: [48, 48],
            iconAnchor: [24, 24],
        });
    };

    const icon = marker.type === "user"
        ? createAvatarIcon(marker.data.name, marker.data.color)
        : createEventIcon(marker.data.color || "#B452FF");

    return (
        <Marker
            position={[marker.lat, marker.lng]}
            icon={icon}
            eventHandlers={{
                click: () => {
                    map.flyTo([marker.lat, marker.lng], 15);
                },
            }}
        >
            <Popup className="custom-popup">
                <div className="p-2 min-w-[200px]">
                    {marker.type === "event" ? (
                        <>
                            <h3 className="text-lg font-black tracking-tight mb-1">{marker.data.title}</h3>
                            <div className="flex items-center gap-2 text-foreground/50 text-xs mb-3">
                                <MapPin className="w-3 h-3" />
                                <span>{marker.data.location}</span>
                            </div>
                            <button className="w-full bg-primary text-white py-2 rounded-xl text-xs font-bold">
                                View Details
                            </button>
                        </>
                    ) : (
                        <div className="flex items-center gap-3">
                            <Avatar name={marker.data.name} color={marker.data.color} size={40} />
                            <div>
                                <h3 className="font-bold text-sm">{marker.data.name}</h3>
                                <p className="text-[10px] text-foreground/40 font-medium">Active now</p>
                            </div>
                        </div>
                    )}
                </div>
            </Popup>
        </Marker>
    );
}
